mapper.select:
SELECT * FROM tb_video_info WHERE is_deleted = 0
AND platform_video_id IN
#{videoId}
AND platform_type IN
#{platformType}

SELECT v.id as videoId, uv.id as extractId, v.platform_type as platformType, v.platform_video_id as platformVideoId, v.title as videoTitle, v.cover_url as videoCover, v.video_url as videoUrl, v.duration as duration, v.publish_time as publishTime, hs.influencer_nickname as influencerNickname, hs.influencer_platform_user_id as influencerPlatformUserId, hs.influencer_avatar as influencerAvatar, hs.influencer_followers_count as followersCount, v.like_count as likeCount, v.comment_count as commentCount, v.share_count as shareCount, v.collect_count as collectCount, CASE WHEN v.like_count > 0 THEN CAST(ROUND(v.comment_count / v.like_count, 2) AS CHAR) ELSE '0.00' END as commentLikeRatio, COALESCE(uv.extract_status, 0) as extractStatus FROM tb_video_hot_search_video hs LEFT JOIN tb_video_info v ON hs.video_id = v.id LEFT JOIN tb_video_user_video uv ON ( uv.video_id = v.id AND uv.tenant_id = #{tenantId} AND uv.source_type = 4 AND uv.is_deleted = 0 ) WHERE hs.search_id = #{searchId} AND hs.is_deleted = 0 AND v.is_deleted = 0
AND v.like_count >= #{queryBo.likeCount}
AND v.comment_count >= #{queryBo.commentCount}
AND v.share_count >= #{queryBo.shareCount}
AND v.collect_count >= #{queryBo.collectCount}
AND v.publish_time >= #{queryBo.publishStartTime}
AND v.publish_time <= #{queryBo.publishEndTime}
AND v.duration >= #{queryBo.durationStartNumber}
AND v.duration <= #{queryBo.durationEndNumber}
AND hs.created_date >= #{videoUpdateStartTime}
AND hs.created_date <= #{videoUpdateEndTime}
AND hs.influencer_followers_count <= 5000
AND hs.influencer_followers_count <= 10000
AND hs.influencer_followers_count <= 20000
AND hs.influencer_followers_count <= 50000
AND hs.influencer_followers_count <= 100000
AND v.like_count > 0 AND (v.comment_count / v.like_count) > 0.05
AND v.like_count > 0 AND (v.comment_count / v.like_count) > 0.10
AND v.like_count > 0 AND (v.comment_count / v.like_count) > 0.15
AND v.like_count > 0 AND (v.comment_count / v.like_count) > 0.20
AND v.like_count > 0 AND (v.comment_count / v.like_count) > 0.25
ORDER BY v.like_count ASC DESC
ORDER BY v.comment_count ASC DESC
ORDER BY v.share_count ASC DESC
ORDER BY v.collect_count ASC DESC
ORDER BY hs.influencer_followers_count ASC DESC
ORDER BY CASE WHEN v.like_count > 0 THEN v.comment_count / v.like_count ELSE 0 END ASC DESC
ORDER BY v.like_count DESC,hs.sort_order ASC

SELECT count(*)
FROM tb_video_info AS v
         LEFT JOIN tb_video_hot_search_video AS hsv ON v.id = hsv.video_id
WHERE hsv.search_id = #{searchId}
  and hsv.is_deleted = 0
  AND v.like_count >= #{likeCount}

SELECT author_id AS authorId, COUNT(*) AS videoCount FROM tb_video_info WHERE author_id IN
#{authorId}
AND is_deleted = 0 GROUP BY author_id

SELECT v.author_id AS authorId, COUNT(*) AS videoCount FROM tb_video_info v WHERE v.is_deleted = 0 AND v.author_id IN
#{authorId}
AND v.id IN ( SELECT uv.video_id FROM tb_video_user_video uv WHERE uv.is_deleted = 0 AND uv.tenant_id = #{tenantId} ) GROUP BY v.author_id

SELECT v.author_id AS authorId, COUNT(*) AS videoCount, COALESCE(SUM(v.like_count), 0) AS totalLikeCount, COALESCE(SUM(v.comment_count), 0) AS totalCommentCount, COALESCE(SUM(v.share_count), 0) AS totalShareCount, COALESCE(SUM(v.collect_count), 0) AS totalCollectCount FROM tb_video_info v WHERE v.is_deleted = 0 AND v.author_id IN
#{authorId}
AND v.publish_time >= #{publishStartTime}
AND v.publish_time <= #{publishEndTime}
GROUP BY v.author_id

SELECT uv.video_id AS videoId, MAX(uv.created_date) AS collectTime FROM tb_video_user_video uv WHERE uv.is_deleted = 0 AND uv.tenant_id = #{tenantId}
AND uv.video_id IN
#{vid}
GROUP BY uv.video_id

SELECT v.id AS videoId, v.title AS title, v.like_count AS likeCount, v.comment_count AS commentCount, v.share_count AS shareCount, v.collect_count AS collectCount, v.duration AS duration, v.publish_time AS publishTime FROM tb_video_info v WHERE v.is_deleted = 0 AND v.author_id = #{authorId}
AND v.platform_type = #{platformType}
AND v.publish_time >= #{publishStartTime}
AND v.publish_time <= #{publishEndTime}
ORDER BY v.publish_time DESC LIMIT #{limit}

SELECT
hs.video_id AS videoId,
CAST( AS CHAR) AS sortVal
FROM tb_video_hot_search_video hs
INNER JOIN tb_video_info v ON v.id = hs.video_id AND v.is_deleted = 0
WHERE hs.is_deleted = 0
AND hs.search_id = #{searchId}


    AND v.author_id IN

        #{aid}



    AND (
     <> #{lastSortVal}
    OR (
     = #{lastSortVal}
    AND hs.video_id <> #{lastVideoId}
    )
    )

ORDER BY
 DESCASC
, hs.video_id DESCASC
LIMIT #{limit}

SELECT v.id AS videoId, v.title AS title, v.author_id AS authorId, v.author_name AS authorName, v.platform_type AS platformType, v.like_count AS likeCount, v.comment_count AS commentCount, v.share_count AS shareCount, v.collect_count AS collectCount, v.duration AS duration, v.publish_time AS publishTime, hs.influencer_nickname AS influencerNickname, hs.influencer_avatar AS influencerAvatar, hs.influencer_followers_count AS influencerFollowersCount, hs.influencer_platform_user_id AS influencerPlatformUserId, hs.influencer_platform_type AS influencerPlatformType FROM tb_video_hot_search_video hs INNER JOIN tb_video_info v ON v.id = hs.video_id AND v.is_deleted = 0 WHERE hs.is_deleted = 0 AND hs.search_id = #{searchId}
AND v.platform_type = #{platformType}
AND v.publish_time >= #{publishStartTime}
AND v.publish_time <= #{publishEndTime}
ORDER BY (COALESCE(v.like_count, 0) + COALESCE(v.comment_count, 0) + COALESCE(v.share_count, 0) + COALESCE(v.collect_count, 0)) DESC, hs.video_id DESC LIMIT #{limit}
